/**
 * Test: ForEach with glide_list type from trigger record field
 *
 * This flow tests metadata extraction when forEach iterates over a glide_list field
 * from a trigger record. The glide_list type should have parent_table_name, column_name,
 * and reference attributes at the pill level.
 *
 * Expected label cache metadata:
 * - Created_1.current.type: parent_table_name="sys_user_group", column_name="type", reference="sys_user"
 * - forEach item pills: <UUID>.item.<property> format
 */

import '@servicenow/sdk/global'
import { Flow, wfa, action } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// Simple Flow with ForEach on glide_list
Flow(
    {
        $id: Now.ID['foreach_metadata_glide_list_flow'],
        name: 'ForEach Metadata - Glide List Test',
        description: 'Tests metadata extraction from glide_list type fields',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['sys_user_group_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.flowLogic.forEach(
            wfa.dataPill(params.trigger.current.additional_assignee_list, 'glide_list'),
            { $id: Now.ID['foreach_items'], annotation: 'Loop through items' },
            (item) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_item'] },
                    {
                        log_message: `Item: ${wfa.dataPill(item.name, 'string')}, Quantity: ${wfa.dataPill(item.name, 'integer')}`,
                        log_level: 'info',
                    }
                )
                wfa.flowLogic.forEach(
                    wfa.dataPill(params.trigger.current.additional_assignee_list, 'glide_list'),
                    { $id: Now.ID['foreach_items_nested'], annotation: 'Loop through items nested' },
                    (item_1) => {
                        wfa.action(
                            action.core.log,
                            { $id: Now.ID['log_item_nested'] },
                            {
                                log_message: `Item: ${wfa.dataPill(item_1, 'glide_list')}, Quantity: ${wfa.dataPill(item_1, 'glide_list')}`,
                                log_level: 'info',
                            }
                        )
                    }
                )
            }
        )
    }
)
